import { Component, ComponentInterface, Element, Fragment, h, Host, Listen, Prop, State } from '@stencil/core';
import { NavigationSizes } from '../../../../types';
import { AriaAttributes, extractAriaAttributes } from '../../../../utils/a11y-helper';

/**
 * @slot default - default slot for the label of the item
 */
@Component({
  tag: 'groupui-local-top-navigation-item',
  styleUrl: 'local-top-navigation-item.scss',
  shadow: { delegatesFocus: true },
})
export class LocalTopNavigationItem implements ComponentInterface {
  /**
   * icon name e.g. 'clock-24'. Use the matching 24px sized icons
   */
  @Prop({ reflect: true }) readonly icon: string;

  /**
   * sets a custom icon source e.g. '...path/clock-24.svg', overrides icon property if both are set
   */
  @Prop({ reflect: true }) readonly iconSource: string;

  /**
   * set item as active
   */
  @Prop({ reflect: true }) readonly active: boolean;

  /**
   * disables the navigation item
   */
  @Prop({ reflect: true }) readonly disabled: boolean;

  /**
   * URL that the hyperlink points to.
   */
  @Prop({ reflect: true }) readonly href: string;

  /**
   * where to open the linked URL. On target 'none' no target attribute will be set.
   */
  @Prop({ reflect: true }) readonly target: string = '_self';

  /**
   * sets a custom accessible text for the icon
   */
  @Prop({ reflect: true, attribute: 'a11y-label-icon' }) readonly a11yLabelIcon: string;

  /**
   * @internal sets the size of the items
   */
  @Prop({ reflect: true }) readonly size: NavigationSizes = 's';

  /**
   * @internal
   */
  @Prop({ reflect: true }) readonly activeMenu: boolean;

  @Element() host: HTMLElement;

  @State() private ariaAttributes: AriaAttributes;

  componentWillLoad(): void {
    this.ariaAttributes = extractAriaAttributes(this.host);
  }

  @Listen('click')
  handleClick(event: Event): void {
    if (this.disabled) {
      event.preventDefault();
      event.stopImmediatePropagation();
    }
  }

  @Listen('keydown')
  handleKeyDown(event: KeyboardEvent): void {
    // "NavItems" should not trigger on space key. If item is a button instead of a link, we have to actively prevent the default action
    if (event.key === ' ') {
      event.preventDefault();
      event.stopImmediatePropagation();
    }
  }

  @Listen('focus')
  handleFocus(event: FocusEvent): void {
    if (this.disabled) {
      event.preventDefault();
      event.stopImmediatePropagation();
      this.host.blur();
    }
  }

  private isInMenu(): boolean {
    return this.host.closest('groupui-menu') !== null;
  }

  render() {
    const commonStyleClasses = { active: this.active, disabled: this.disabled, item: true };

    const navItemContent = (
      <Fragment>
        {this.icon && (
          <groupui-icon
            name={this.icon}
            aria-hidden={this.a11yLabelIcon ? null : 'true'}
            src={this.iconSource}
            alt={this.a11yLabelIcon}
          />
        )}
        <slot />
        {this.isInMenu() && (
          <groupui-icon name={this.activeMenu ? 'chevron-up-24' : 'chevron-down-24'} aria-hidden="true" />
        )}
      </Fragment>
    );

    return (
      <Host>
        <div aria-disabled={this.disabled && 'true'} aria-current={this.active && 'page'}>
          {this.href ? (
            <a
              tabIndex={this.disabled ? -1 : 0}
              href={this.href}
              target={this.target}
              class={commonStyleClasses}
              {...this.ariaAttributes}
            >
              {navItemContent}
            </a>
          ) : (
            <button
              tabIndex={this.disabled ? -1 : 0}
              type="button"
              disabled={this.disabled}
              class={commonStyleClasses}
              {...this.ariaAttributes}
            >
              {navItemContent}
            </button>
          )}
        </div>
      </Host>
    );
  }
}
